Describe 'EXP-141 Edge Performance Detector zero-mutation integration' -Tag Integration {
 BeforeAll{$script:providerPath=Join-Path $PSScriptRoot '..\providers\EdgeDisablePerformanceDetector.ps1';$script:isWindows=$IsWindows;$script:enabled=($env:LACKSAN_RUN_WINDOWS_INTEGRATION -eq '1')}
 It 'Check performs no declared mutation' -Skip:(-not $script:isWindows -or -not $script:enabled){$before=(Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Edge\Recommended' -Name PerformanceDetectorEnabled -ErrorAction SilentlyContinue).PerformanceDetectorEnabled;& $script:providerPath -Action Check -StatePath (Join-Path $TestDrive 'state.json') -LogPath (Join-Path $TestDrive 'events.jsonl') -ProfileFixturePath (Join-Path $TestDrive 'profile') -ErrorAction SilentlyContinue|Out-Null;$after=(Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Edge\Recommended' -Name PerformanceDetectorEnabled -ErrorAction SilentlyContinue).PerformanceDetectorEnabled;$after|Should -Be $before}
 It 'DryRun performs no declared mutation when support gates allow execution' -Skip:(-not $script:isWindows -or -not $script:enabled){$before=(Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Edge\Recommended' -Name PerformanceDetectorEnabled -ErrorAction SilentlyContinue).PerformanceDetectorEnabled;try{& $script:providerPath -Action DryRun -StatePath (Join-Path $TestDrive 'state.json') -LogPath (Join-Path $TestDrive 'events.jsonl') -ProfileFixturePath (Join-Path $TestDrive 'profile')|Out-Null}catch{};$after=(Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Edge\Recommended' -Name PerformanceDetectorEnabled -ErrorAction SilentlyContinue).PerformanceDetectorEnabled;$after|Should -Be $before}
}
